"use client";

import Link from "next/link";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  asArray, asObject, contactState, contextLabel, discoverySignal, facts, formatDate, inferences, intelligence, lensLabel, latestRun, needsReview,
  operatorContactState, operatorNextAction, operatorPersonLabel, operatorRoleLabel, operatorWorkflowState, operatorWhyRelevant, organisationName, primaryOpportunity, prospectPriority, prospectType, resolutionLabel, reviewDecision, reviewReason, runCounts, shortId, siteTypeLabel, sourceType, statusLabel, territoryLabel, unknowns, contactShortLabel, type OperatorCandidate,
  type OperatorPayload, type OperatorRun,
} from "../../src/operator-ui/logic";

function useOperatorData(query: string) {
  const [data, setData] = useState<OperatorPayload & { selectedRun?: OperatorRun | null }>({ access: "VIEWER", runs: [], candidates: [], latestRunId: null });
  const [state, setState] = useState<"loading" | "ready" | "error">("loading");
  useEffect(() => { setState("loading"); fetch(`/api/operator?${query}`).then(async (response) => { if (!response.ok) throw new Error((await response.json()).message); return response.json(); }).then((value) => { setData(value); setState("ready"); }).catch(() => setState("error")); }, [query]);
  return { data, state };
}

function PageHeader({ eyebrow, title, lede, action, compact = false }: { eyebrow: string; title: string; lede: string; action?: React.ReactNode; compact?: boolean }) {
  return <header className={compact ? "operator-page-header compact" : "operator-page-header"}><div><span className="operator-kicker">{eyebrow}</span><h1>{title}</h1><p>{lede}</p></div>{action}</header>;
}

function Badge({ children, tone = "neutral" }: { children: React.ReactNode; tone?: string }) { return <span className={`operator-badge ${tone}`}>{children}</span>; }
function Loading({ label = "Loading operator data…" }: { label?: string }) { return <div className="operator-empty"><span className="operator-kicker">PLEASE WAIT</span><p>{label}</p></div>; }
function ErrorState() { return <div className="operator-empty error"><span className="operator-kicker">DATA UNAVAILABLE</span><h2>Operator data could not be loaded.</h2><p>Check that discovery persistence is available and try again.</p></div>; }
function EmptyState({ title, text }: { title: string; text: string }) { return <div className="operator-empty"><span className="operator-kicker">NO RESULTS</span><h2>{title}</h2><p>{text}</p></div>; }

function Stats({ run, candidates }: { run: OperatorRun | null; candidates: OperatorCandidate[] }) {
  const counts = runCounts(run, candidates);
  const values = [["Found", counts.found], ["Resolved", counts.resolved], ["Unresolved", counts.unresolved], ["Enriched", counts.enriched], ["Advanced", counts.advanced], ["Qualified", counts.qualified], ["Review", counts.review], ["Rejected", counts.rejected], ["Contactable", counts.contactable]];
  return <div className="operator-stats">{values.map(([label, value]) => <div className="operator-stat" key={label}><span>{label}</span><strong>{value}</strong></div>)}</div>;
}

function RunMeta({ run, compact = false }: { run: OperatorRun; compact?: boolean }) {
  const summary = asObject(run.summary);
  return <div className={compact ? "run-meta compact" : "run-meta"}><div><span className="operator-label">TERRITORY</span><strong>{territoryLabel(run.territory_code)}</strong></div><div><span className="operator-label">LENS</span><strong>{lensLabel(run.focus)}</strong></div><div><span className="operator-label">STATUS</span><Badge tone={run.status.toLowerCase()}>{run.status}</Badge></div>{!compact ? <><div><span className="operator-label">STARTED</span><strong>{formatDate(run.started_at ?? run.created_at)}</strong></div><div><span className="operator-label">COMPLETED</span><strong>{formatDate(run.completed_at)}</strong></div><div><span className="operator-label">RUN ID</span><strong className="mono">{shortId(run.id)}</strong></div></> : null}<span className="sr-only">Summary fields available: {Object.keys(summary).join(", ")}</span></div>;
}

function ResearchBrief({ run }: { run: OperatorRun }) {
  const summary = asObject(run.summary);
  const metadata = asObject(summary.provenance ?? summary.metadata);
  const brief = String(summary.researchBrief ?? summary.brief ?? "");
  return <section className="research-brief"><div><span className="operator-kicker">RESEARCH BRIEF</span><h2>{brief || "Research instruction not recorded for this run"}</h2><p>{brief ? "Plain-language instruction context for this run." : "Not recorded for this run. The interface does not infer private prompts or hidden model instructions."}</p></div><dl className="provenance-list"><div><dt>TRIGGER / SOURCE</dt><dd>{String(metadata.trigger ?? metadata.source ?? "Not recorded for this run")}</dd></div><div><dt>DISCOVERY PATH</dt><dd>{String(metadata.discoveryPath ?? "Not recorded for this run")}</dd></div><div><dt>RESEARCH LIMIT</dt><dd>{String(metadata.maxCandidates ?? asObject(run.budget).maxCandidates ?? "Not recorded for this run")}</dd></div><div><dt>APPLICATION VERSION</dt><dd>{String(metadata.commitSha ?? metadata.deploymentVersion ?? "Not recorded for this run")}</dd></div></dl></section>;
}

function CollectionTable({ label, count, children, className = "" }: { label: string; count: number; children: React.ReactNode; className?: string }) {
  return <div className={`collection-table-wrap ${className} ${label === "Prospects" ? "prospect-queue-table" : ""}`}><table className="collection-table"><caption className="sr-only">{label}</caption>{children}</table><div className="collection-count">{count} records in this view</div></div>;
}

function SortButton({ label, active, direction, onClick }: { label: string; active: boolean; direction: "asc" | "desc"; onClick: () => void }) {
  return <button className={active ? "table-sort active" : "table-sort"} type="button" onClick={onClick}>{label}{active ? <span aria-hidden="true"> {direction === "asc" ? "↑" : "↓"}</span> : null}</button>;
}

function Pagination({ page, pageSize, total, onPage, onPageSize }: { page: number; pageSize: number; total: number; onPage: (page: number) => void; onPageSize: (size: number) => void }) {
  const pages = Math.max(1, Math.ceil(total / pageSize)); const start = total ? (page - 1) * pageSize + 1 : 0; const end = Math.min(page * pageSize, total);
  return <div className="pagination"><span>{start}–{end} of {total}</span><label>Rows <select value={pageSize} onChange={(event) => { onPageSize(Number(event.target.value)); onPage(1); }}><option value="25">25</option><option value="50">50</option><option value="100">100</option></select></label><button type="button" disabled={page <= 1} onClick={() => onPage(page - 1)}>Previous</button><span>Page {page} of {pages}</span><button type="button" disabled={page >= pages} onClick={() => onPage(page + 1)}>Next</button></div>;
}

function CandidateLink({ candidate }: { candidate: OperatorCandidate }) { return <Link className="table-action" href={`/operator/prospects/${candidate.id}`}>Open ↗</Link>; }

function CandidateRow({ candidate, latestRunId, onSelect, selected = false, review = false, showAttention = true }: { candidate: OperatorCandidate; latestRunId: string | null; onSelect?: () => void; selected?: boolean; review?: boolean; showAttention?: boolean }) {
  const unresolved = organisationName(candidate) === "ORGANISATION NOT YET RESOLVED";
  return <tr className={selected ? "is-selected" : undefined} tabIndex={onSelect ? 0 : undefined} aria-selected={onSelect ? selected : undefined} onClick={onSelect} onKeyDown={(event) => { if (onSelect && (event.key === "Enter" || event.key === " ")) { event.preventDefault(); onSelect(); } }}>
    {review ? <><td className="decision-cell"><strong>{reviewReason(candidate)}</strong><span>Specific decision required</span></td><td><strong className={unresolved ? "unresolved" : undefined}>{organisationName(candidate)}</strong><span>{territoryLabel(candidate.territory_code)}</span></td><td><strong>{discoverySignal(candidate)}</strong><span>{candidate.origin.replaceAll("_", " ")}</span></td><td><span>{reviewReason(candidate)}</span></td><td><span>{primaryOpportunity(candidate)}</span></td><td><span>{contactShortLabel(candidate)}</span></td><td><span>{formatDate(candidate.created_at, "Not recorded")}</span><small>{contextLabel(candidate, latestRunId)}</small></td><td><span>{shortId(candidate.discovery_run_id)}</span></td></> : <><td><strong className={unresolved ? "unresolved" : undefined}>{organisationName(candidate)}</strong><span>{territoryLabel(candidate.territory_code)}</span></td><td><strong>{discoverySignal(candidate)}</strong><span>{candidate.origin.replaceAll("_", " ")}</span></td><td><span>{siteTypeLabel(sourceType(candidate))}</span></td><td><Badge tone={resolutionLabel(candidate).toLowerCase().includes("resolved") ? "verified" : "review_required"}>{resolutionLabel(candidate)}</Badge></td><td><span>{primaryOpportunity(candidate)}</span></td><td><span>{contactShortLabel(candidate)}</span></td><td><Badge tone={candidate.status.toLowerCase()}>{statusLabel(candidate.status)}</Badge></td>{showAttention ? <td>{needsReview(candidate) ? <Badge tone="review_required">Needs decision</Badge> : <span>—</span>}</td> : null}<td><span>{formatDate(candidate.created_at, "Not recorded")}</span><small>{contextLabel(candidate, latestRunId)} · {shortId(candidate.discovery_run_id)}</small></td></>}
    <td><CandidateLink candidate={candidate} /></td>
  </tr>;
}

function CandidateInspector({ candidate, latestRunId, onClose }: { candidate: OperatorCandidate; latestRunId: string | null; onClose: () => void }) {
  const value = intelligence(candidate); const resolution = asObject(value.organisationResolution); const target = organisationName(candidate); const unknown = unknowns(candidate)[0] ?? "No important unknown recorded.";
  return <aside className="quick-inspector" aria-label="Quick prospect inspector"><div className="inspector-heading"><div><span className="operator-kicker">QUICK INSPECTOR</span><h2>{target}</h2></div><button className="inspector-close" type="button" onClick={onClose} aria-label="Close inspector">×</button></div><section><span className="operator-label">WHO WE THINK THE CUSTOMER IS</span><strong>{target}</strong><p>{resolution.officialWebsite ?? candidate.account?.website ?? "Authoritative site not recorded"}</p><p>Resolution: {resolutionLabel(candidate)}</p></section><section><span className="operator-label">WHAT WE FOUND</span><strong>{discoverySignal(candidate)}</strong><p>{siteTypeLabel(sourceType(candidate))} · {territoryLabel(candidate.territory_code)}</p></section><section><span className="operator-label">WHY IT MATTERS</span><strong>{primaryOpportunity(candidate)}</strong><p>{String(asArray<any>(value.commercialEvidence ?? value.evidence)[0]?.claim ?? value.eventConnection?.reasons?.[0] ?? "Commercial evidence not recorded")}</p><p className="inspector-unknown">Unknown / blocker: {unknown}</p></section><section><span className="operator-label">CONTACT</span><strong>{contactShortLabel(candidate)}</strong><p>{candidate.contacts?.length ? "Persisted public ownership evidence is available." : "No verified ownership evidence is shown."}</p></section><section><span className="operator-label">DECISION / NEXT ACTION</span><strong>{reviewDecision(candidate) || String(value.recommendedNextAction ?? "No specific human decision required")}</strong><p>{contextLabel(candidate, latestRunId)} · {statusLabel(candidate.status)}</p></section><Link className="operator-button" href={`/operator/prospects/${candidate.id}`}>Open full prospect ↗</Link></aside>;
}

function CandidateCard({ candidate, latestRunId }: { candidate: OperatorCandidate; latestRunId: string | null }) {
  return <Link href={`/operator/prospects/${candidate.id}`} className="candidate-card"><div className="candidate-card-top"><Badge tone={contextLabel(candidate, latestRunId).toLowerCase()}>{contextLabel(candidate, latestRunId)}</Badge><Badge tone={candidate.status.toLowerCase()}>{statusLabel(candidate.status)}</Badge></div><h3>{organisationName(candidate)}</h3><p>{discoverySignal(candidate)} <span>·</span> {territoryLabel(candidate.territory_code)}</p><div className="candidate-facts"><span>{primaryOpportunity(candidate)}</span><span>{contactShortLabel(candidate)}</span><span>{siteTypeLabel(sourceType(candidate))}</span></div><div className="found-run"><span className="operator-label">FOUND IN RUN</span><strong>{formatDate(candidate.created_at)} · {shortId(candidate.discovery_run_id)}</strong></div></Link>;
}

export function OverviewView() {
  const { data, state } = useOperatorData("view=overview");
  if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />;
  const run = latestRun(data.runs); const candidates = data.candidates.filter((candidate) => candidate.discovery_run_id === run?.id); const attention = candidates.filter(needsReview);
  return <><PageHeader eyebrow="AI SALES TEAM" title="What did the team just find?" lede="Supervise the latest bounded research run, inspect its evidence, and focus only on decisions that genuinely need your attention." action={run ? <Link className="operator-button" href={`/operator/runs/${run.id}`}>View latest run ↗</Link> : undefined} />{run ? <><section className="latest-run-panel"><div className="latest-run-heading"><div><Badge tone="current">LATEST RUN</Badge><h2>{territoryLabel(run.territory_code)} <span>·</span> {lensLabel(run.focus)}</h2><p>{formatDate(run.completed_at ?? run.created_at)} · {run.status.toLowerCase()}</p></div><span className="operator-label">RUN {shortId(run.id)}</span></div><ResearchBrief run={run} /><Stats run={run} candidates={candidates} /></section><section className="attention-section"><div className="section-heading"><span className="operator-kicker">WHAT NEEDS YOUR ATTENTION?</span><span className="muted">{attention.length} decision-oriented items</span></div>{attention.length ? <div className="attention-list">{attention.slice(0, 4).map((candidate) => <CandidateCard candidate={candidate} latestRunId={data.latestRunId} key={candidate.id} />)}</div> : <EmptyState title="No human decision is currently required." text="Research can continue without manufacturing a review task." />}</section></> : <EmptyState title="No recent runs" text="No bounded prospecting runs are available. Historical records remain separate when they exist." />}</>;
}

export function RunsView() {
  const { data, state } = useOperatorData("view=runs"); const [filter, setFilter] = useState("ALL"); const [sort, setSort] = useState<"date" | "territory" | "status" | "review">("date"); const [direction, setDirection] = useState<"asc" | "desc">("desc");
  const latest = data.latestRunId; const runs = useMemo(() => data.runs.filter((run) => filter === "ALL" || (filter === "LATEST" ? run.id === latest : filter === "FAILED" ? ["FAILED", "ERROR"].includes(run.status) : filter === "REVIEW" ? runCounts(run, data.candidates).review > 0 : runCounts(run, data.candidates).qualified > 0)).sort((a, b) => { const av = sort === "date" ? new Date(a.created_at ?? a.started_at ?? 0).getTime() : sort === "territory" ? territoryLabel(a.territory_code) : sort === "status" ? a.status : String(runCounts(a, data.candidates).review); const bv = sort === "date" ? new Date(b.created_at ?? b.started_at ?? 0).getTime() : sort === "territory" ? territoryLabel(b.territory_code) : sort === "status" ? b.status : String(runCounts(b, data.candidates).review); return (av < bv ? -1 : av > bv ? 1 : 0) * (direction === "asc" ? 1 : -1); }), [data.candidates, data.runs, direction, filter, latest, sort]); if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />;
  const changeSort = (next: typeof sort) => { if (sort === next) setDirection(direction === "asc" ? "desc" : "asc"); else { setSort(next); setDirection(next === "date" ? "desc" : "asc"); } };
  return <><PageHeader eyebrow="RUNS" title="Bounded research runs" lede="Scan, compare and filter research runs. Open a run only when you need its scoped candidates and provenance." /><div className="quick-filter-bar" role="toolbar" aria-label="Run quick filters">{["ALL", "LATEST", "REVIEW", "QUALIFIED", "FAILED"].map((value) => <button key={value} type="button" className={filter === value ? "quick-filter active" : "quick-filter"} onClick={() => setFilter(value)}>{value === "ALL" ? "All runs" : value === "REVIEW" ? "Has review" : value === "QUALIFIED" ? "Has qualified" : value[0] + value.slice(1).toLowerCase()}</button>)}</div>{runs.length ? <CollectionTable label="Research runs" count={runs.length}><thead><tr><th><SortButton label="STARTED" active={sort === "date"} direction={direction} onClick={() => changeSort("date")} /></th><th><SortButton label="TERRITORY" active={sort === "territory"} direction={direction} onClick={() => changeSort("territory")} /></th><th>LENS</th><th><SortButton label="STATUS" active={sort === "status"} direction={direction} onClick={() => changeSort("status")} /></th><th>FOUND</th><th>RESOLVED</th><th>ADVANCED</th><th>QUALIFIED</th><th>REVIEW</th><th>REJECTED</th><th>CONTACTABLE</th><th>ACTION</th></tr></thead><tbody>{runs.map((run) => { const counts = runCounts(run, data.candidates); return <tr key={run.id}><td><strong>{run.id === latest ? <Badge tone="current">LATEST</Badge> : null}</strong><span>{formatDate(run.started_at ?? run.created_at)}</span></td><td>{territoryLabel(run.territory_code)}</td><td>{lensLabel(run.focus)}</td><td><Badge tone={run.status.toLowerCase()}>{run.status}</Badge></td><td>{counts.found}</td><td>{counts.resolved}</td><td>{counts.advanced}</td><td>{counts.qualified}</td><td>{counts.review}</td><td>{counts.rejected}</td><td>{counts.contactable}</td><td><Link className="table-action" href={`/operator/runs/${run.id}`}>Inspect ↗</Link></td></tr>; })}</tbody></CollectionTable> : <EmptyState title="No runs match this filter" text="Try a wider run scope. No records were changed." />}</>;
}

export function RunDetailView({ runId }: { runId: string }) {
  const { data, state } = useOperatorData(`view=run&runId=${encodeURIComponent(runId)}`); if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />;
  const run = data.selectedRun ?? data.runs.find((item) => item.id === runId) ?? null; const candidates = data.candidates;
  if (!run) return <EmptyState title="Run not found" text="This run may not be available to the current member." />;
  return <><PageHeader eyebrow="RUN DETAIL" title={`${territoryLabel(run.territory_code)} · ${lensLabel(run.focus)}`} lede="The run summary and provenance stay above a compact candidate collection scoped to this run only." action={<Link className="operator-button secondary" href="/operator/runs">Back to runs</Link>} /><div className="detail-banner"><RunMeta run={run} /><ResearchBrief run={run} /><Stats run={run} candidates={candidates} /></div><section className="candidate-section"><div className="section-heading"><span className="operator-kicker">CANDIDATES IN THIS RUN ONLY</span><span className="muted">{candidates.length} records</span></div>{candidates.length ? <CollectionTable label="Candidates in this run" count={candidates.length}><thead><tr><th>ORGANISATION</th><th>DISCOVERY SIGNAL</th><th>SOURCE</th><th>RESOLUTION</th><th>OPPORTUNITY</th><th>CONTACT</th><th>STATUS</th><th>ATTENTION</th><th>ACTION</th></tr></thead><tbody>{candidates.map((candidate) => <CandidateRow key={candidate.id} candidate={candidate} latestRunId={data.latestRunId} />)}</tbody></CollectionTable> : <EmptyState title="No candidates in this run" text="The run completed without persisted candidates." />}</section><details className="diagnostics"><summary>Diagnostics (collapsed)</summary><div className="provenance-list"><div><span className="operator-label">RUN ID</span><strong className="mono">{run.id}</strong></div><div><span className="operator-label">PROVIDER / MODEL</span><strong>{run.provider ?? "Not recorded"} · {run.model ?? "Not recorded"}</strong></div><div><span className="operator-label">TECHNICAL OUTCOME</span><strong>{run.status}</strong></div><div><span className="operator-label">ERROR CONTEXT</span><strong>{run.error_message ?? "None recorded"}</strong></div></div><p className="muted">Private prompts, secrets, API keys and hidden reasoning are never rendered.</p></details></>;
}

export function LegacyProspectsView() {
  const { data, state } = useOperatorData("view=prospects"); const [query, setQuery] = useState(""); const [scope, setScope] = useState("ACTIVE"); const [territory, setTerritory] = useState("ALL"); const [source, setSource] = useState("ALL"); const [resolution, setResolution] = useState("ALL"); const [opportunity, setOpportunity] = useState("ALL"); const [status, setStatus] = useState("ALL"); const [contact, setContact] = useState("ALL"); const [sort, setSort] = useState<"attention" | "organisation" | "found" | "status">("attention"); const [direction, setDirection] = useState<"asc" | "desc">("desc"); const [page, setPage] = useState(1); const [pageSize, setPageSize] = useState(50); const [selectedId, setSelectedId] = useState<string | null>(null);
  const latest = data.latestRunId; const filtered = useMemo(() => { const text = query.toLowerCase(); return data.candidates.filter((candidate) => { const intelligenceValue = intelligence(candidate); const searchable = `${organisationName(candidate)} ${candidate.candidate_name} ${candidate.website ?? ""} ${sourceType(candidate)}`.toLowerCase(); const context = contextLabel(candidate, latest); const candidateResolution = resolutionLabel(candidate); const candidateOpportunity = primaryOpportunity(candidate); return (!text || searchable.includes(text)) && (scope === "ALL" || (scope === "ACTIVE" ? ["NEW", "CURRENT"].includes(context) && !["REJECTED", "DUPLICATE"].includes(candidate.status) : scope === "REVIEW" ? needsReview(candidate) : scope === "QUALIFIED" ? candidate.status === "QUALIFIED" : scope === "UNRESOLVED" ? candidateResolution === "Unresolved" : scope === "NO_CONTACT" ? contactShortLabel(candidate) === "No verified target contact" : scope === "PROVIDER" ? sourceType(candidate) === "TICKETING_PROVIDER" : ["HISTORICAL", "CALIBRATION", "LEGACY"].includes(context))) && (territory === "ALL" || candidate.territory_code === territory) && (source === "ALL" || sourceType(candidate) === source) && (resolution === "ALL" || (resolution === "RESOLVED" ? candidateResolution.startsWith("Resolved") : candidateResolution === "Unresolved")) && (opportunity === "ALL" || candidateOpportunity.toUpperCase().includes(opportunity)) && (status === "ALL" || candidate.status === status) && (contact === "ALL" || (contact === "VERIFIED" ? contactShortLabel(candidate) === "Verified target contact" : contactShortLabel(candidate) !== "Verified target contact")); }); }, [contact, data.candidates, latest, opportunity, query, resolution, scope, source, status, territory]);
  const sorted = useMemo(() => [...filtered].sort((a, b) => { const attention = (candidate: OperatorCandidate) => needsReview(candidate) ? 2 : candidate.status === "QUALIFIED" ? 1 : 0; const av = sort === "organisation" ? organisationName(a) : sort === "status" ? a.status : sort === "found" ? new Date(a.created_at ?? 0).getTime() : attention(a); const bv = sort === "organisation" ? organisationName(b) : sort === "status" ? b.status : sort === "found" ? new Date(b.created_at ?? 0).getTime() : attention(b); return (av < bv ? -1 : av > bv ? 1 : 0) * (direction === "asc" ? 1 : -1); }), [direction, filtered, sort]);
  if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />;
  const visible = sorted.slice((page - 1) * pageSize, page * pageSize); const selected = data.candidates.find((candidate) => candidate.id === selectedId) ?? null; const changeSort = (next: typeof sort) => { if (sort === next) setDirection(direction === "asc" ? "desc" : "asc"); else { setSort(next); setDirection(next === "found" ? "desc" : "asc"); } setPage(1); }; const clearFilters = () => { setQuery(""); setScope("ACTIVE"); setTerritory("ALL"); setSource("ALL"); setResolution("ALL"); setOpportunity("ALL"); setStatus("ALL"); setContact("ALL"); setPage(1); };
  return <><PageHeader eyebrow="PROSPECTS" title="Commercial targets, not CRM records" lede="Scan, compare and inspect the collection without turning provider or listing pages into prospect identity." /><div className="quick-filter-bar" role="toolbar" aria-label="Prospect quick filters">{[["ACTIVE", "Latest run"], ["REVIEW", "Needs review"], ["QUALIFIED", "Qualified"], ["UNRESOLVED", "Unresolved"], ["NO_CONTACT", "No verified contact"], ["PROVIDER", "Ticketing-provider source"], ["ALL", "Historical / all"]].map(([value, label]) => <button key={value} type="button" className={scope === value ? "quick-filter active" : "quick-filter"} onClick={() => { setScope(value); setPage(1); }}>{label}</button>)}<button type="button" className="quick-filter clear" onClick={clearFilters}>Clear filters</button></div><div className="filter-panel"><label>Search<input value={query} onChange={(event) => { setQuery(event.target.value); setPage(1); }} placeholder="Organisation, event or source" /></label><label>Territory<select value={territory} onChange={(event) => { setTerritory(event.target.value); setPage(1); }}><option value="ALL">All territories</option><option value="ZA">South Africa</option><option value="GB">United Kingdom</option></select></label><label>Source type<select value={source} onChange={(event) => { setSource(event.target.value); setPage(1); }}><option value="ALL">All sources</option>{Object.keys(siteTypeLabelsForFilter).map((key) => <option key={key} value={key}>{siteTypeLabel(key)}</option>)}</select></label><label>Resolution<select value={resolution} onChange={(event) => { setResolution(event.target.value); setPage(1); }}><option value="ALL">All resolution</option><option value="RESOLVED">Resolved</option><option value="UNRESOLVED">Unresolved</option></select></label><label>Opportunity<select value={opportunity} onChange={(event) => { setOpportunity(event.target.value); setPage(1); }}><option value="ALL">All opportunities</option><option value="EVENT GROWTH">Event Growth</option><option value="TICKETING">Ticketing</option><option value="EVENT OPERATIONS">Event Operations</option></select></label><label>Status<select value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="ALL">All statuses</option>{Object.keys(statusLabelsForFilter).map((key) => <option key={key} value={key}>{statusLabel(key)}</option>)}</select></label><label>Contact<select value={contact} onChange={(event) => { setContact(event.target.value); setPage(1); }}><option value="ALL">All contactability</option><option value="VERIFIED">Verified target contact</option><option value="NONE">No verified target contact</option></select></label></div><div className="collection-toolbar"><span><strong>{filtered.length}</strong> matching records · page before filter is {data.candidates.length}</span><label>Sort <select value={sort} onChange={(event) => changeSort(event.target.value as typeof sort)}><option value="attention">Attention then recency</option><option value="found">Found date</option><option value="organisation">Organisation</option><option value="status">Status</option></select></label></div>{visible.length ? <div className={selected ? "collection-with-inspector has-inspector" : "collection-with-inspector"}><CollectionTable label="Prospects" count={filtered.length}><thead><tr><th><SortButton label="ORGANISATION" active={sort === "organisation"} direction={direction} onClick={() => changeSort("organisation")} /></th><th>DISCOVERY SIGNAL</th><th>SOURCE</th><th>RESOLUTION</th><th>OPPORTUNITY</th><th>CONTACT</th><th>STATUS</th><th>ATTENTION</th><th><SortButton label="FOUND" active={sort === "found"} direction={direction} onClick={() => changeSort("found")} /></th><th>ACTION</th></tr></thead><tbody>{visible.map((candidate) => <CandidateRow key={candidate.id} candidate={candidate} latestRunId={latest} selected={candidate.id === selectedId} onSelect={() => setSelectedId(candidate.id)} showAttention />)}</tbody></CollectionTable>{selected ? <CandidateInspector candidate={selected} latestRunId={latest} onClose={() => setSelectedId(null)} /> : null}</div> : <EmptyState title="No prospects match these filters" text="Try a wider scope or clear the active filters. No records were changed." />}<Pagination page={page} pageSize={pageSize} total={sorted.length} onPage={setPage} onPageSize={setPageSize} /></>;
}

function ProspectQueueRow({ candidate, selected, onOpen }: { candidate: OperatorCandidate; selected: boolean; onOpen: (id: string, trigger: HTMLElement) => void }) {
  const secondary = String(asObject(candidate.account?.metadata).eventName ?? candidate.candidate_name ?? "Activity not recorded");
  const status = operatorWorkflowState(candidate);
  return <tr className={selected ? "is-selected" : undefined} tabIndex={0} aria-selected={selected} onClick={(event) => onOpen(candidate.id, event.currentTarget)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); onOpen(candidate.id, event.currentTarget); } }}>
    <td><strong>{organisationName(candidate)}</strong><span>{secondary}</span><small>{territoryLabel(candidate.territory_code)}</small></td>
    <td>{prospectType(candidate)}</td>
    <td><span className="queue-why">{operatorWhyRelevant(candidate)}</span></td>
    <td>{operatorPersonLabel(candidate)}</td>
    <td><Badge tone={status.toLowerCase().replaceAll(" ", "_")}>{status}</Badge></td>
    <td><button type="button" className="queue-action" onClick={(event) => { event.stopPropagation(); onOpen(candidate.id, event.currentTarget); }}>{operatorNextAction(candidate)}</button></td>
  </tr>;
}

function ProspectDrawer({ candidate, onClose, restoreFocus }: { candidate: OperatorCandidate; onClose: () => void; restoreFocus: HTMLElement | null }) {
  const closeRef = useRef<HTMLButtonElement | null>(null);
  const [tab, setTab] = useState<"Overview" | "People" | "Email" | "History">("Overview");
  const [composerMessage, setComposerMessage] = useState("Draft-only Composer actions remain supervised and never send.");
  const value = intelligence(candidate);
  const resolution = asObject(value.organisationResolution);
  const fit = [value.egs, value.ticketing, value.ecc].map((item: unknown) => asObject(item)).filter((item) => item.opportunityStrength || item.rationale);
  const contacts = candidate.contacts ?? [];
  const composer = asObject(asObject(candidate.account?.metadata).outreachComposer);
  const drafts = asArray<any>(composer.drafts);
  const canPrepareDraft = Boolean(candidate.account_id && contacts.length);
  useEffect(() => {
    closeRef.current?.focus();
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") { event.preventDefault(); onClose(); return; }
      if (event.key !== "Tab") return;
      const focusable = Array.from(document.querySelectorAll<HTMLElement>('[data-prospect-drawer] button, [data-prospect-drawer] a, [data-prospect-drawer] input, [data-prospect-drawer] textarea, [data-prospect-drawer] select')).filter((item) => !item.hasAttribute("disabled"));
      if (!focusable.length) return;
      const first = focusable[0]; const last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => { document.removeEventListener("keydown", onKeyDown); restoreFocus?.focus(); };
  }, [onClose, restoreFocus]);
  async function prepareDraft() {
    if (!candidate.account_id) { setComposerMessage("A resolved account is required before a draft can be prepared."); return; }
    setComposerMessage("Preparing a draft for human review…");
    try {
      const response = await fetch("/api/ai-sales/outreach-composer", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "prepare", accountId: candidate.account_id, briefId: asObject(candidate.account?.metadata).aiSalesBriefId, sequenceStage: "EMAIL_1" }) });
      const payload = await response.json();
      if (!response.ok) throw new Error(payload.message ?? "Composer is unavailable.");
      setComposerMessage("Draft prepared. Review each message separately in the Email tab.");
    } catch (error) { setComposerMessage(error instanceof Error ? error.message : "Composer is unavailable."); }
  }
  function overview() {
    const unresolved = String(resolution.status ?? "UNRESOLVED").toUpperCase() !== "RESOLVED";
    const needs = [...unknowns(candidate), ...(unresolved ? ["Event organiser not confirmed"] : []), ...(!contacts.length ? ["Buyer not identified"] : []), ...(operatorContactState(candidate) === "No email found" ? ["Contact route not found"] : [])];
    return <div className="prospect-tab-content"><section className="drawer-lead"><span className="operator-kicker">WHY THIS PROSPECT?</span><p>{operatorWhyRelevant(candidate)}</p></section><section className="drawer-action-card"><span className="operator-kicker">RECOMMENDED NEXT STEP</span><h3>{operatorNextAction(candidate) === "Confirm organiser" ? "Confirm the event organiser before looking for a buyer." : operatorNextAction(candidate)}</h3><button type="button" className="operator-button" onClick={() => setTab(operatorNextAction(candidate) === "Review email" ? "Email" : "People")}>{operatorNextAction(candidate)}</button></section><section className="drawer-section"><h3>At a glance</h3><dl className="drawer-definition-list"><div><dt>Prospect type</dt><dd>{prospectType(candidate)}</dd></div><div><dt>Event</dt><dd>{String(asObject(candidate.account?.metadata).eventName ?? candidate.candidate_name ?? "Not recorded")}</dd></div><div><dt>Organisation</dt><dd>{organisationName(candidate)}</dd></div><div><dt>Location</dt><dd>{territoryLabel(candidate.territory_code)}</dd></div><div><dt>Website</dt><dd>{candidate.account?.website || candidate.website ? <a href={candidate.account?.website ?? candidate.website ?? "#"} target="_blank" rel="noreferrer">{candidate.account?.website ?? candidate.website}</a> : "Not recorded"}</dd></div><div><dt>Latest activity</dt><dd>{String(value.eventFreshness?.state ?? "Not recorded").replaceAll("_", " ")}</dd></div><div><dt>Identity state</dt><dd>{operatorWorkflowState(candidate)}</dd></div><div><dt>Priority</dt><dd>{prospectPriority(candidate)}</dd></div></dl></section><section className="drawer-section"><h3>What we know</h3>{facts(candidate).length ? facts(candidate).slice(0, 4).map((fact: any, index) => <p className="drawer-fact" key={index}>{fact.claim ?? fact.text}{fact.sourceUrl ? <a href={fact.sourceUrl} target="_blank" rel="noreferrer">{fact.sourceTitle ?? "Source"} ↗</a> : null}</p>) : <p className="drawer-muted">Evidence is still being assembled.</p>}</section><section className="drawer-section"><h3>What needs checking</h3>{needs.length ? <ul className="drawer-list">{needs.slice(0, 5).map((item, index) => <li key={`${item}-${index}`}>{item}</li>)}</ul> : <p className="drawer-muted">No immediate checks are outstanding.</p>}</section><section className="drawer-section"><h3>EventSuite fit</h3>{fit.length ? <div className="fit-summary">{fit.map((item, index) => <div key={index}><strong>{["Event Growth Studio", "Ticketing", "Event Operations"][index]}</strong><span>{String(item.opportunityStrength ?? item.rationale ?? "Assessed").replaceAll("_", " ")}</span></div>)}</div> : <p className="drawer-muted">We have not assessed EventSuite fit yet.</p>}</section></div>;
  }
  function people() {
    return <div className="prospect-tab-content"><section className="drawer-section"><h3>Potential people</h3>{contacts.length ? contacts.map((contact: any, index) => <article className="person-row" key={String(contact.id ?? index)}><div><strong>{String(contact.full_name ?? contact.name ?? "Named contact")}</strong><span>{String(contact.role_title ?? contact.role ?? "Role not recorded")}</span><small>{String(candidate.account?.name ?? organisationName(candidate))}</small></div><div><strong>{operatorRoleLabel(asObject(contact.metadata).buyerRoutingClassification ?? asObject(contact.metadata).personClassification)}</strong><span>{operatorContactState(candidate)}</span><small>{String(asObject(contact.metadata).publicEvidence ?? "Public ownership evidence recorded")}</small></div></article>) : <p className="drawer-empty">No suitable person has been identified yet.</p>}</section><section className="drawer-section"><h3>Selected person</h3><p>{contacts.length ? operatorPersonLabel(candidate) : "No person selected"}</p></section><section className="drawer-section"><h3>Business email</h3><p>{operatorContactState(candidate)}</p><p className="drawer-muted">Human selection remains mandatory before any enrichment.</p></section></div>;
  }
  function email() {
    return <div className="prospect-tab-content"><p className="drawer-muted">Composer drafts remain isolated, draft-only and separately reviewed. No send, schedule or enrolment action is available.</p>{(["EMAIL_1", "EMAIL_2", "EMAIL_3"] as const).map((stage, index) => { const draft = drafts.find((item) => item.sequenceStage === stage || item.sequence_stage === stage); return <article className="email-stage" key={stage}><div className="email-stage-heading"><h3>Email {index + 1} — {index === 0 ? "Introduction" : index === 1 ? "Try EventSuite" : "Final note"}</h3><span>{draft ? (draft.approved ? "Draft approved — not sent" : "Draft awaiting approval") : "No draft yet"}</span></div>{draft ? <><label>Subject<input defaultValue={draft.subject ?? ""} /></label><label>Body<textarea defaultValue={draft.bodyPlainText ?? draft.body_plain_text ?? ""} rows={8} /></label><p className="signature-preview">Raphael Domalik<br />EventSuite<br />raphael@eventsuite.pro<br />LinkedIn: https://www.linkedin.com/in/raphaeldomalik/<br />eventsuite.pro</p><p className="drawer-muted">Evidence used: {asArray(draft.personalisationEvidenceIds ?? draft.structured_output?.personalisationEvidenceIds).join(", ") || "Not recorded"}</p><div className="drawer-actions"><button type="button">Edit</button><button type="button">Request revision</button><button type="button">Approve draft</button><button type="button">Reject draft</button></div></> : index === 0 ? <><button type="button" className="operator-button" disabled={!canPrepareDraft} onClick={() => void prepareDraft()}>Generate draft</button>{!canPrepareDraft ? <p className="drawer-muted">Confirm identity and select a person with validated ownership before drafting.</p> : null}</> : <p className="drawer-muted">Email 1 must be reviewed before this stage is prepared.</p>}</article>; })}<p role="status" className="drawer-status">{composerMessage}</p></div>;
  }
  function history() {
    const events = [{ label: "Prospect recorded", date: candidate.created_at }, ...facts(candidate).slice(0, 3).map((fact: any) => ({ label: fact.claim ?? "Evidence recorded", date: fact.observedAt ?? candidate.last_seen_at })), ...(contacts.length ? [{ label: "Person evidence available", date: candidate.last_seen_at }] : []), ...(drafts.length ? [{ label: "Draft generated", date: candidate.last_seen_at }] : [])];
    return <div className="prospect-tab-content"><section className="drawer-section"><h3>Review history</h3><ol className="history-timeline">{events.map((item, index) => <li key={index}><strong>{item.label}</strong><span>{formatDate(item.date, "Date not recorded")}</span></li>)}</ol></section><details className="technical-details"><summary>Technical details</summary><p>Source classification, provider outcomes, prompt versions and deterministic codes remain available to authorised review tooling but are not part of the primary operator workflow.</p><p className="mono">Candidate reference: {candidate.id}</p></details></div>;
  }
  return <div className="prospect-drawer-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><aside className="prospect-drawer" data-prospect-drawer role="dialog" aria-modal="true" aria-label={`Review ${organisationName(candidate)}`}><header className="prospect-drawer-header"><div><span className="operator-kicker">{prospectType(candidate)}</span><h2>{organisationName(candidate)}</h2><p>{String(asObject(candidate.account?.metadata).eventName ?? candidate.candidate_name ?? "Prospect")}</p></div><div className="drawer-header-actions"><Badge tone={operatorWorkflowState(candidate).toLowerCase().replaceAll(" ", "_")}>{operatorWorkflowState(candidate)}</Badge><button ref={closeRef} type="button" className="inspector-close" onClick={onClose} aria-label="Close prospect drawer">×</button></div></header><div className="drawer-progress" aria-label="Review progress"><span className="active">Prospect</span><span>Person</span><span>Email</span><span>Approval</span></div><nav className="drawer-tabs" role="tablist" aria-label="Prospect review tabs">{(["Overview", "People", "Email", "History"] as const).map((item) => <button type="button" role="tab" className={tab === item ? "active" : undefined} aria-selected={tab === item} onClick={() => setTab(item)} key={item}>{item}</button>)}</nav>{tab === "Overview" ? overview() : tab === "People" ? people() : tab === "Email" ? email() : history()}</aside></div>;
}

export function ProspectsView() {
  const { data, state } = useOperatorData("view=prospects");
  const [queue, setQueue] = useState("NEEDS_REVIEW"); const [query, setQuery] = useState(""); const [territory, setTerritory] = useState("ALL"); const [prospectTypeFilter, setProspectTypeFilter] = useState("ALL"); const [reviewState, setReviewState] = useState("ALL"); const [contactFilter, setContactFilter] = useState("ALL"); const [emailFilter, setEmailFilter] = useState("ALL"); const [priority, setPriority] = useState("ALL"); const [showFilters, setShowFilters] = useState(false); const [sort, setSort] = useState("attention"); const [page, setPage] = useState(1); const [pageSize, setPageSize] = useState(25); const [selectedId, setSelectedId] = useState<string | null>(null); const [restoreFocus, setRestoreFocus] = useState<HTMLElement | null>(null);
  useEffect(() => { const sync = () => setSelectedId(new URL(window.location.href).searchParams.get("prospect")); sync(); window.addEventListener("popstate", sync); return () => window.removeEventListener("popstate", sync); }, []);
  const openDrawer = (id: string, trigger: HTMLElement) => { const url = new URL(window.location.href); url.searchParams.set("prospect", id); window.history.pushState({ prospect: id }, "", url); setRestoreFocus(trigger); setSelectedId(id); };
  const closeDrawer = () => { const url = new URL(window.location.href); url.searchParams.delete("prospect"); window.history.replaceState({}, "", url); setSelectedId(null); };
  const archive = (candidate: OperatorCandidate) => ["REJECTED", "BLOCKED", "DUPLICATE"].includes(candidate.status) || Boolean(candidate.dedupe_of_candidate_id) || ["HISTORICAL", "CALIBRATION", "LEGACY"].includes(contextLabel(candidate, data.latestRunId));
  const inQueue = (candidate: OperatorCandidate) => { const status = operatorWorkflowState(candidate); if (queue === "ALL") return true; if (queue === "ARCHIVE") return archive(candidate); if (archive(candidate)) return false; if (queue === "NEEDS_REVIEW") return ["Needs identity review", "Contact needs review", "Draft awaiting approval"].includes(status); if (queue === "READY_PEOPLE") return status === "Ready for person review"; if (queue === "DRAFTS") return status === "Draft awaiting approval"; if (queue === "APPROVED") return status === "Draft approved — not sent"; if (queue === "DEFERRED") return status === "Deferred"; return false; };
  const counts = useMemo(() => Object.fromEntries([["NEEDS_REVIEW", "Needs review"], ["READY_PEOPLE", "Ready for people"], ["DRAFTS", "Drafts to review"], ["APPROVED", "Approved drafts"], ["DEFERRED", "Deferred"], ["ARCHIVE", "Archive"], ["ALL", "All"]].map(([key, label]) => [key, { label, count: data.candidates.filter((candidate) => { if (key === "ALL") return true; if (key === "ARCHIVE") return archive(candidate); if (archive(candidate)) return false; const status = operatorWorkflowState(candidate); if (key === "NEEDS_REVIEW") return ["Needs identity review", "Contact needs review", "Draft awaiting approval"].includes(status); if (key === "READY_PEOPLE") return status === "Ready for person review"; if (key === "DRAFTS") return status === "Draft awaiting approval"; if (key === "APPROVED") return status === "Draft approved — not sent"; if (key === "DEFERRED") return status === "Deferred"; return false; }).length }])), [data.candidates]);
  const filtered = useMemo(() => { const text = query.trim().toLowerCase(); return data.candidates.filter((candidate) => { const searchable = `${organisationName(candidate)} ${candidate.candidate_name} ${operatorWhyRelevant(candidate)}`.toLowerCase(); return inQueue(candidate) && (!text || searchable.includes(text)) && (territory === "ALL" || candidate.territory_code === territory) && (prospectTypeFilter === "ALL" || prospectType(candidate) === prospectTypeFilter) && (reviewState === "ALL" || operatorWorkflowState(candidate) === reviewState) && (contactFilter === "ALL" || (contactFilter === "PERSON" ? Boolean(candidate.contacts?.length) : !candidate.contacts?.length)) && (emailFilter === "ALL" || (emailFilter === "VERIFIED" ? operatorContactState(candidate) === "Business email verified" : operatorContactState(candidate) !== "Business email verified")) && (priority === "ALL" || prospectPriority(candidate) === priority); }); }, [contactFilter, data.candidates, emailFilter, priority, prospectTypeFilter, query, reviewState, territory, queue]);
  const sorted = useMemo(() => [...filtered].sort((a, b) => { if (sort === "name") return organisationName(a).localeCompare(organisationName(b)); if (sort === "recent") return new Date(b.last_seen_at ?? b.created_at ?? 0).getTime() - new Date(a.last_seen_at ?? a.created_at ?? 0).getTime(); if (sort === "ready") return operatorNextAction(a).localeCompare(operatorNextAction(b)); return operatorWorkflowState(a).localeCompare(operatorWorkflowState(b)); }), [filtered, sort]);
  if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />;
  const visible = sorted.slice((page - 1) * pageSize, page * pageSize); const selected = data.candidates.find((candidate) => candidate.id === selectedId) ?? null;
  const reset = () => { setQueue("NEEDS_REVIEW"); setQuery(""); setTerritory("ALL"); setProspectTypeFilter("ALL"); setReviewState("ALL"); setContactFilter("ALL"); setEmailFilter("ALL"); setPriority("ALL"); setPage(1); };
  return <><PageHeader compact eyebrow="PROSPECTS" title="Prospects" lede="Review potential EventSuite customers and decide what happens next." /><div className="prospect-queue-tabs" role="tablist" aria-label="Prospect queues">{Object.entries(counts).map(([key, item]) => <button key={key} type="button" role="tab" aria-selected={queue === key} className={queue === key ? "active" : undefined} onClick={() => { setQueue(key); setPage(1); }}>{item.label}<span>{item.count}</span></button>)}</div><div className="prospect-toolbar"><label className="prospect-search">Search<input value={query} onChange={(event) => { setQuery(event.target.value); setPage(1); }} placeholder="Search prospects" /></label><button type="button" className={showFilters ? "filter-toggle active" : "filter-toggle"} onClick={() => setShowFilters(!showFilters)} aria-expanded={showFilters}>Filters</button><label className="sort-control">Sort<select value={sort} onChange={(event) => setSort(event.target.value)}><option value="attention">Needs attention first</option><option value="recent">Most recent</option><option value="name">Prospect name</option><option value="ready">Ready for review</option></select></label></div>{showFilters ? <div className="prospect-filter-panel"><label>Prospect type<select value={prospectTypeFilter} onChange={(event) => setProspectTypeFilter(event.target.value)}><option value="ALL">All types</option><option value="Event">Event</option><option value="Organisation">Organisation</option><option value="Person">Person</option><option value="Venue">Venue</option></select></label><label>Territory<select value={territory} onChange={(event) => setTerritory(event.target.value)}><option value="ALL">All territories</option><option value="ZA">South Africa</option><option value="GB">United Kingdom</option></select></label><label>Review state<select value={reviewState} onChange={(event) => setReviewState(event.target.value)}><option value="ALL">All states</option><option value="Needs identity review">Needs identity review</option><option value="Ready for person review">Ready for person review</option><option value="Contact needs review">Contact needs review</option></select></label><label>Contact state<select value={contactFilter} onChange={(event) => setContactFilter(event.target.value)}><option value="ALL">All people</option><option value="PERSON">Person identified</option><option value="NONE">No person selected</option></select></label><label>Email state<select value={emailFilter} onChange={(event) => setEmailFilter(event.target.value)}><option value="ALL">All email states</option><option value="VERIFIED">Business email verified</option><option value="REVIEW">Needs review / not found</option></select></label><label>Priority<select value={priority} onChange={(event) => setPriority(event.target.value)}><option value="ALL">All priorities</option><option value="Phase One priority">Phase One priority</option><option value="Standard priority">Standard priority</option><option value="Deferred">Deferred</option></select></label><button type="button" className="clear-filter-button" onClick={reset}>Clear filters</button></div> : null}<div className="prospect-filter-chips">{queue !== "NEEDS_REVIEW" ? <span>{counts[queue as keyof typeof counts]?.label}</span> : null}{territory !== "ALL" ? <span>{territoryLabel(territory)}</span> : null}{prospectTypeFilter !== "ALL" ? <span>{prospectTypeFilter}</span> : null}{query ? <span>Search: {query}</span> : null}</div><div className="collection-toolbar prospect-count"><span><strong>{filtered.length} prospects</strong>{queue === "ALL" ? " shown" : ""}</span><span>{filtered.length ? "Select a row to review the prospect." : "No prospects need action in this view."}</span></div>{visible.length ? <CollectionTable label="Prospects" count={filtered.length}><thead><tr><th>Prospect</th><th>Type</th><th>Why relevant</th><th>Person and email</th><th>Status</th><th>Next action</th></tr></thead><tbody>{visible.map((candidate) => <ProspectQueueRow key={candidate.id} candidate={candidate} selected={candidate.id === selectedId} onOpen={openDrawer} />)}</tbody></CollectionTable> : <EmptyState title="No prospects in this queue" text="Try another queue or adjust the filters. No records were changed." />}<Pagination page={page} pageSize={pageSize} total={sorted.length} onPage={setPage} onPageSize={setPageSize} />{selected ? <ProspectDrawer candidate={selected} onClose={closeDrawer} restoreFocus={restoreFocus} /> : null}</>;
}
const siteTypeLabelsForFilter = { ORGANISATION_OFFICIAL: true, EVENT_OFFICIAL: true, TICKETING_PROVIDER: true, EVENT_LISTING_DIRECTORY: true, VENUE_OFFICIAL: true, VENUE_CALENDAR: true, SOCIAL_COMMUNITY: true, NEWS_EDITORIAL: true, UNKNOWN: true };
const statusLabelsForFilter = { REVIEW_REQUIRED: true, QUALIFIED: true, REJECTED: true, BLOCKED: true, DUPLICATE: true, DISCOVERED: true, RESOLVED: true };

function EvidenceList({ label, items, kind }: { label: string; items: Array<Record<string, any>>; kind: "FACT" | "INFERENCE" | "UNKNOWN" }) { return <section className={`evidence-block ${kind.toLowerCase()}`}><div className="section-heading"><span className="operator-kicker">{label}</span><Badge tone={kind.toLowerCase()}>{kind}</Badge></div>{items.length ? items.map((item, index) => <article className="evidence-item" key={`${kind}-${index}`}><p>{typeof item === "string" ? item : item.claim ?? item.text ?? "Evidence detail not recorded"}</p>{typeof item === "object" && item.sourceUrl ? <a href={item.sourceUrl} target="_blank" rel="noreferrer">{item.sourceTitle ?? "Open source"} ↗</a> : null}<span>{typeof item === "object" ? item.confidence ?? "Confidence not recorded" : "Important unanswered question"}</span></article>) : <p className="muted">None recorded.</p>}</section>; }

function Lens({ label, value }: { label: string; value: any }) { const item = asObject(value); return <article className="lens-card"><div className="lens-title"><span className="operator-kicker">{label}</span><Badge tone="neutral">{String(item.opportunityStrength ?? item.status ?? "UNKNOWN").replaceAll("_", " ")}</Badge></div><p>{String(item.rationale ?? item.summary ?? "No conclusion recorded for this lens.")}</p><div className="lens-evidence"><strong>FACTS</strong><span>{asArray(item.facts ?? item.evidence).slice(0, 3).map((entry: any) => typeof entry === "string" ? entry : entry.claim).join(" · ") || "None recorded"}</span></div></article>; }

function Contactability({ candidate }: { candidate: OperatorCandidate }) { const contacts = candidate.contacts ?? []; const research = asObject(candidate.contact_research); return <section className="contact-section"><div className="section-heading"><span className="operator-kicker">CONTACTABILITY</span><Badge tone={contacts.length ? "verified" : "neutral"}>{contactState(candidate)}</Badge></div>{contacts.length ? contacts.map((contact, index) => { const metadata = asObject(contact.metadata); return <article className="contact-card" key={String(contact.id ?? index)}><strong>{String(contact.email ?? contact.phone ?? contact.full_name ?? contact.name ?? "Public route")}</strong><dl><div><dt>OWNER</dt><dd>{String(candidate.account?.name ?? "Resolved target not recorded")}</dd></div><div><dt>SOURCE</dt><dd>{String(metadata.sourceTitle ?? metadata.sourceUrl ?? "Source not recorded")}</dd></div><div><dt>WHY WE BELIEVE IT BELONGS</dt><dd>{String(metadata.publicEvidence ?? "Ownership evidence not recorded")}</dd></div></dl><Badge tone="verified">{String(contact.verification_status ?? "VERIFIED")}</Badge></article>; }) : <div className="contact-empty"><strong>NO VERIFIED TARGET CONTACT</strong><p>{research.status === "CONTACT_RESEARCH_REQUIRED" ? "Contact research is required before a route can be presented as usable." : "No persisted contact evidence establishes a usable route for the resolved target."}</p></div>}</section>; }

export function ProspectDetailView({ candidateId }: { candidateId: string }) {
  const { data, state } = useOperatorData(`view=prospect&candidateId=${encodeURIComponent(candidateId)}`); if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />;
  const candidate = data.candidates[0]; if (!candidate) return <EmptyState title="Prospect not found" text="This record may not be available to the current member." />;
  const value = intelligence(candidate); const resolution = asObject(value.organisationResolution); const target = candidate.organiser_name || candidate.account?.name; const source = sourceType(candidate);
  return <><PageHeader eyebrow="PROSPECT DETAIL" title={target ?? "ORGANISATION NOT YET RESOLVED"} lede="Follow the evidence story from discovery signal to commercial target, then inspect contactability and the recommended next action." action={<Link className="operator-button secondary" href="/operator/prospects">Back to prospects</Link>} /><div className="origin-strip"><span className="operator-label">FOUND IN RUN</span><strong>{formatDate(candidate.created_at)} · {territoryLabel(candidate.territory_code)} · {lensLabel(asObject(data.runs.find((run) => run.id === candidate.discovery_run_id)).focus)} · {shortId(candidate.discovery_run_id)}</strong><Badge tone={contextLabel(candidate, data.latestRunId).toLowerCase()}>{contextLabel(candidate, data.latestRunId)}</Badge></div><section className="target-header"><div><span className="operator-kicker">RESOLVED COMMERCIAL TARGET</span><h2>{target ?? "ORGANISATION NOT YET RESOLVED"}</h2><p>{candidate.account?.website ? <a href={candidate.account.website} target="_blank" rel="noreferrer">{candidate.account.website} ↗</a> : "Authoritative organisation website not recorded"}</p></div><dl><div><dt>RESOLUTION</dt><dd>{String(resolution.status ?? "UNRESOLVED")}</dd></div><div><dt>CONFIDENCE</dt><dd>{String(resolution.confidence ?? "Not recorded")}</dd></div><div><dt>OPPORTUNITY</dt><dd>{primaryOpportunity(candidate)}</dd></div><div><dt>STATUS</dt><dd><Badge tone={candidate.status.toLowerCase()}>{statusLabel(candidate.status)}</Badge></dd></div></dl></section><div className="story-grid"><section className="story-section"><div className="story-heading"><span className="operator-kicker">WHAT WE FOUND</span><Badge tone="neutral">{siteTypeLabel(source)}</Badge></div><h2>{candidate.candidate_name}</h2><p>Origin: {candidate.origin.replaceAll("_", " ")} · Source: {siteTypeLabel(source)}</p>{candidate.website ? <a href={candidate.website} target="_blank" rel="noreferrer">Open discovery source ↗</a> : <p className="muted">Discovery URL not recorded.</p>}<p>{String(value.eventConnection?.reasons?.[0] ?? "Discovery signal context is recorded in the evidence below.")}</p></section><section className="story-section"><div className="story-heading"><span className="operator-kicker">WHO WE THINK THE CUSTOMER IS</span><Badge tone={resolution.status === "RESOLVED" ? "verified" : "neutral"}>{resolution.status === "RESOLVED" ? "Resolved" : "Unresolved"}</Badge></div><p>{String(resolution.evidence?.[0]?.claim ?? "The persisted evidence does not establish organiser responsibility yet.")}</p>{resolution.officialWebsite ? <a href={resolution.officialWebsite} target="_blank" rel="noreferrer">Open official organisation site ↗</a> : null}</section></div><section className="identity-section"><div className="section-heading"><span className="operator-kicker">IDENTITY / ORGANISER EVIDENCE</span></div><EvidenceList label="Organiser evidence" items={asArray(resolution.evidence)} kind="FACT" /></section><section className="event-context"><div className="section-heading"><span className="operator-kicker">EVENT / ACTIVITY CONTEXT</span></div><div className="context-columns"><div><span className="operator-label">FRESHNESS</span><strong>{String(value.eventFreshness?.state ?? "Not recorded")}</strong></div><div><span className="operator-label">RELATIONSHIP</span><strong>{candidate.relationship}</strong></div><div><span className="operator-label">ALIASES</span><strong>{asArray(resolution.aliases).join(" · ") || "None recorded"}</strong></div></div></section><section className="commercial-section"><div className="section-heading"><span className="operator-kicker">COMMERCIAL INTELLIGENCE</span><span className="muted">EventSuite hypotheses remain separate</span></div><div className="lens-grid"><Lens label="EVENT GROWTH" value={value.egs} /><Lens label="TICKETING" value={value.ticketing} /><Lens label="EVENT OPERATIONS" value={value.ecc} /></div><div className="evidence-grid"><EvidenceList label="FACTS" items={facts(candidate)} kind="FACT" /><EvidenceList label="INFERENCES" items={inferences(candidate)} kind="INFERENCE" /><EvidenceList label="UNKNOWNS" items={unknowns(candidate).map((item) => ({ text: item }))} kind="UNKNOWN" /></div></section><section className="buyer-section"><div className="section-heading"><span className="operator-kicker">BUYER / PROBLEM OWNER</span></div><h2>{asArray(value.buyerProblemOwner?.likelyRoles).join(" · ") || "Role not established"}</h2><p>{String(value.buyerProblemOwner?.rationale ?? "A named person is not shown without public evidence.")}</p></section><Contactability candidate={candidate} /><section className="recommendation"><span className="operator-kicker">AI RECOMMENDATION</span><h2>{String(value.recommendedNextAction ?? "No recommendation recorded")}</h2><p>{String(value.outreachBlockOrReviewReason ?? value.nextBestCommercialAction?.rationale ?? "No additional rationale recorded.")}</p><Badge tone={needsReview(candidate) ? "review_required" : "neutral"}>{needsReview(candidate) ? "Needs your decision" : "No human action required"}</Badge></section><details className="diagnostics"><summary>Diagnostics (collapsed)</summary><p>Candidate ID: <span className="mono">{candidate.id}</span></p><p>Origin run: <span className="mono">{candidate.discovery_run_id}</span></p><p>Raw JSON is intentionally not required for normal operator understanding.</p></details></>;
}

export function ReviewView() { const { data, state } = useOperatorData("view=review"); if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />; const items = data.candidates.filter(needsReview); return <><PageHeader eyebrow="NEEDS YOUR DECISION" title="A decision queue, not a failure bucket" lede="The first column states the specific human decision. Generic ‘needs more research’ items stay out of this queue." />{items.length ? <CollectionTable label="Needs Review" count={items.length}><thead><tr><th>DECISION REQUIRED</th><th>ORGANISATION</th><th>DISCOVERY SIGNAL</th><th>WHY BLOCKED</th><th>OPPORTUNITY</th><th>CONTACT</th><th>FOUND / AGE</th><th>RUN</th><th>ACTION</th></tr></thead><tbody>{items.map((candidate) => <CandidateRow key={candidate.id} candidate={candidate} latestRunId={data.latestRunId} review />)}</tbody></CollectionTable> : <EmptyState title="No decision-oriented items" text="The AI Sales Team has no specific human decision to request right now." />}</> }

export function HistoricalView() { const { data, state } = useOperatorData("view=historical"); if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />; const items = data.candidates.filter((candidate) => ["HISTORICAL", "CALIBRATION", "LEGACY"].includes(contextLabel(candidate, data.latestRunId))); return <><PageHeader eyebrow="HISTORICAL / CALIBRATION" title="Inspect old evidence safely" lede="A dense, searchable collection for older results. Replay remains deferred and historical context is never presented as current sales work." /><div className="future-compare"><span className="operator-kicker">FUTURE COMPARISON SPACE</span><strong>ORIGINAL HISTORICAL RESULT <span>vs</span> CURRENT REPLAY RESULT</strong><p>Replay is deliberately not implemented in V1.</p></div>{items.length ? <CollectionTable label="Historical and calibration records" count={items.length}><thead><tr><th>CONTEXT</th><th>DATE / RUN</th><th>ORGANISATION OR SIGNAL</th><th>TERRITORY</th><th>SOURCE</th><th>ORIGINAL STATUS</th><th>CURRENT INTERPRETATION</th><th>EVALUATION CONTEXT</th><th>ACTION</th></tr></thead><tbody>{items.map((candidate) => <tr key={candidate.id}><td><Badge tone={contextLabel(candidate, data.latestRunId).toLowerCase()}>{contextLabel(candidate, data.latestRunId)}</Badge></td><td><span>{formatDate(candidate.created_at)}</span><small>{shortId(candidate.discovery_run_id)}</small></td><td><strong>{organisationName(candidate)}</strong><span>{discoverySignal(candidate)}</span></td><td>{territoryLabel(candidate.territory_code)}</td><td>{siteTypeLabel(sourceType(candidate))}</td><td><Badge tone={candidate.status.toLowerCase()}>{statusLabel(candidate.status)}</Badge></td><td>{candidate.status === "QUALIFIED" ? "Previously qualified; inspect current evidence" : "Historical evidence only"}</td><td>{contextLabel(candidate, data.latestRunId) === "CALIBRATION" ? "Calibration context retained" : "No replay evaluation"}</td><td><CandidateLink candidate={candidate} /></td></tr>)}</tbody></CollectionTable> : <EmptyState title="No historical records in the current data window" text="Records are labelled conservatively; calibration or legacy context is not fabricated when it is not persisted." />}</> }
